// =========================================================================
// HQ-001: AzureHound / BloodHound â€“ Directory Enumeration via Group Policy Reads
// =========================================================================
// Description : Detects burst reads of GroupLifecyclePolicies, a low-noise
//               signal produced by AzureHound and ROADtools when they map 
//               the tenant's group model. Five or more calls in one hour from
//               the same actor is abnormal for normal user/admin activity.
// MITRE ATT&CK: TA0007 Discovery
//               T1069.003 â€“ Permission Groups Discovery: Cloud Groups
//               T1087.004 â€“ Account Discovery: Cloud Account
// Tools       : AzureHound, BloodHoundAD, ROADtools
// Severity    : Medium
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

AuditLogs
| where TimeGenerated > ago(1d)
| where ActivityDisplayName == "GroupLifecyclePolicies_Get"
| extend InitiatedByUPN  = tostring(InitiatedBy.user.userPrincipalName)
| extend InitiatedByUser = tostring(InitiatedBy.user.displayName)
| extend InitiatedByApp  = tostring(InitiatedBy.app.displayName)
| extend InitiatedBySPId = tostring(InitiatedBy.app.servicePrincipalId)
| extend Actor = iff(isnotempty(InitiatedByUPN), InitiatedByUPN, InitiatedByApp)
| summarize
    ActionCount    = count(),
    FirstSeen      = min(TimeGenerated),
    LastSeen       = max(TimeGenerated),
    Services       = make_set(LoggedByService),
    CorrelationIds = make_set(CorrelationId, 5)
    by Actor, InitiatedBySPId, AADTenantId, bin(TimeGenerated, 1h)
| where ActionCount >= 5
| extend DurationMinutes = datetime_diff('minute', LastSeen, FirstSeen)
| extend RatePerMinute   = round(toreal(ActionCount) / iff(DurationMinutes == 0, 1.0, toreal(DurationMinutes)), 2)
| project-reorder TimeGenerated, Actor, ActionCount, RatePerMinute, DurationMinutes, FirstSeen, LastSeen
| order by ActionCount desc

// =========================================================================
// HQ-002: New Application Registration with Immediate Credential Addition
// =========================================================================
// Description : Joins app creation events with credential-add events within
//               a 5-minute window. Legitimate DevOps pipelines register apps
//               and add secrets, but so do ROADtools and MicroBurst when
//               setting up OAuth infrastructure for token abuse or persistence.
//               Review the actor and app display name for anomalies.
// MITRE ATT&CK: TA0003 Persistence
//               T1098.001 â€“ Additional Cloud Credentials
// Tools       : ROADtools, MicroBurst, AADInternals, CloudKatana
// Severity    : Medium-High
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

let Lookback       = 1d;
let CredWindow     = 5m;

let AppCreations = AuditLogs
| where TimeGenerated > ago(Lookback)
| where ActivityDisplayName in (
    "Add application",
    "Create application \u2013 Certificates and secrets management ")
| extend AppObjectId   = tostring(TargetResources[0].id)
| extend AppName       = tostring(TargetResources[0].displayName)
| extend CreatorUPN    = tostring(InitiatedBy.user.userPrincipalName)
| extend CreatorApp    = tostring(InitiatedBy.app.displayName)
| extend CreatorActor  = iff(isnotempty(CreatorUPN), CreatorUPN, CreatorApp)
| project CreatedAt = TimeGenerated, AppObjectId, AppName, CreatorActor, CreatorUPN, CreatorApp, CorrelationId;

let CredAdds = AuditLogs
| where TimeGenerated > ago(Lookback)
| where ActivityDisplayName in (
    "Update application \u2013 Certificates and secrets management ",
    "Create application \u2013 Certificates and secrets management ",
    "Add service principal credentials",
    "Update service principal")
| mv-expand Prop = TargetResources[0].modifiedProperties
| where tostring(Prop.displayName) has_any ("KeyCredentials","PasswordCredentials","Credential","Secret","Certificate")
| extend AppObjectId    = tostring(TargetResources[0].id)
| extend AppName        = tostring(TargetResources[0].displayName)
| extend CredActorUPN   = tostring(InitiatedBy.user.userPrincipalName)
| extend CredActorApp   = tostring(InitiatedBy.app.displayName)
| extend CredActor      = iff(isnotempty(CredActorUPN), CredActorUPN, CredActorApp)
| extend CredType       = tostring(Prop.displayName)
| project CredAddedAt = TimeGenerated, AppObjectId, AppName, CredActor, CredActorUPN, CredType;

AppCreations
| join kind=inner CredAdds on AppObjectId
| where CredAddedAt > CreatedAt
| where CredAddedAt <= CreatedAt + CredWindow
| extend MinutesBetween = datetime_diff('minute', CredAddedAt, CreatedAt)
| project
    AppName,
    AppObjectId,
    CreatedAt,
    CredAddedAt,
    MinutesBetween,
    CreatorActor,
    CredActor,
    CredType
| order by CreatedAt desc

// =========================================================================
// HQ-003: OAuth Consent Grants â€“ Actors with Multiple App Consents
// =========================================================================
// Description : Surfaces users or service principals that consented to,
//               or granted delegated permissions for, multiple applications
//               within the last 7 days. Token-abuse tools (TokenTactics,
//               ROADtools) often consent to custom apps to obtain broad
//               delegated tokens. Also covers admin-consent phishing.
// MITRE ATT&CK: TA0006 Credential Access
//               T1528 â€“ Steal Application Access Token
// Tools       : TokenTactics, ROADtools, AADInternals
// Severity    : Medium
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

AuditLogs
| where TimeGenerated > ago(7d)
| where ActivityDisplayName in (
    "Consent to application",
    "Add delegated permission grant",
    "Add app role assignment to service principal")
| extend InitiatedByUPN  = tostring(InitiatedBy.user.userPrincipalName)
| extend InitiatedByUser = tostring(InitiatedBy.user.displayName)
| extend InitiatedByApp  = tostring(InitiatedBy.app.displayName)
| extend Actor           = iff(isnotempty(InitiatedByUPN), InitiatedByUPN, InitiatedByApp)
| extend TargetApp       = tostring(TargetResources[0].displayName)
| extend TargetAppId     = tostring(TargetResources[0].id)
| extend PermDetail      = tostring(AdditionalDetails)
| summarize
    ConsentCount      = count(),
    AppsConsented     = make_set(TargetApp, 20),
    AppIds            = make_set(TargetAppId, 20),
    Operations        = make_set(ActivityDisplayName),
    FirstConsent      = min(TimeGenerated),
    LastConsent       = max(TimeGenerated),
    CorrelationIds    = make_set(CorrelationId, 5)
    by Actor
| where ConsentCount >= 2 or array_length(AppsConsented) >= 2
| extend DaysBetween = datetime_diff('day', LastConsent, FirstConsent)
| order by ConsentCount desc

// =========================================================================
// HQ-004: Burst Service Principal Creations in 1-Hour Window
// =========================================================================
// Description : Detects three or more service principals created by the
//               same actor within a one-hour bucket. MicroBurst, ROADtools
//               and CloudKatana register SPs in bulk when setting up attack
//               infrastructure. Legitimate admins rarely create more than
//               one or two SPs in rapid succession.
// MITRE ATT&CK: TA0003 Persistence
//               T1136.003 â€“ Create Cloud Account
// Tools       : ROADtools, MicroBurst, CloudKatana, AADInternals
// Severity    : Medium
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

AuditLogs
| where TimeGenerated > ago(1d)
| where ActivityDisplayName == "Add service principal"
| extend InitiatedByUPN = tostring(InitiatedBy.user.userPrincipalName)
| extend InitiatedByApp = tostring(InitiatedBy.app.displayName)
| extend Actor          = iff(isnotempty(InitiatedByUPN), InitiatedByUPN, InitiatedByApp)
| extend NewSPName      = tostring(TargetResources[0].displayName)
| extend NewSPId        = tostring(TargetResources[0].id)
| summarize
    SPCreatedCount = count(),
    SPNames        = make_set(NewSPName, 20),
    SPIds          = make_set(NewSPId, 20),
    FirstCreation  = min(TimeGenerated),
    LastCreation   = max(TimeGenerated)
    by Actor, bin(TimeGenerated, 1h)
| where SPCreatedCount >= 3
| extend DurationMinutes = datetime_diff('minute', LastCreation, FirstCreation)
| extend RatePerMinute   = round(toreal(SPCreatedCount) / iff(DurationMinutes == 0, 1.0, toreal(DurationMinutes)), 2)
| order by SPCreatedCount desc

// =========================================================================
// HQ-005: Privileged Role Assignment NOT Logged by PIM
// =========================================================================
// Description : All legitimate role assignments in a PIM-enabled tenant
//               should be logged with LoggedByService = "PIM". Direct 
//               role assignments via the Azure portal, PowerShell, or
//               attacker tools (AADInternals, MicroBurst) will appear with
//               LoggedByService = "Core Directory". This query surfaces
//               those non-PIM assignments.
// MITRE ATT&CK: TA0004 Privilege Escalation
//               T1098.003 â€“ Additional Cloud Roles
// Tools       : AADInternals, MicroBurst, manual attacker
// Severity    : High
// Note        : If PIM is not licensed/enabled in your tenant, adjust the
//               filter or suppress the LoggedByService condition.
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

AuditLogs
| where TimeGenerated > ago(7d)
| where ActivityDisplayName in (
    "Add member to role",
    "Add eligible member to role",
    "Add scoped member to role",
    "Add permanent member to role")
| where LoggedByService !in ("PIM", "Privileged Identity Management")
| extend InitiatedByUPN  = tostring(InitiatedBy.user.userPrincipalName)
| extend InitiatedByApp  = tostring(InitiatedBy.app.displayName)
| extend Actor           = iff(isnotempty(InitiatedByUPN), InitiatedByUPN, InitiatedByApp)
| extend TargetUser      = tostring(TargetResources[0].displayName)
| extend TargetUserUPN   = tostring(TargetResources[0].userPrincipalName)
| extend RoleName        = tostring(TargetResources[1].displayName)
| where Result == "success"
| project
    TimeGenerated,
    Actor,
    TargetUser,
    TargetUserUPN,
    RoleName,
    ActivityDisplayName,
    LoggedByService,
    CorrelationId
| order by TimeGenerated desc

// =========================================================================
// HQ-006: External / Guest User Receiving Group or Role Membership
// =========================================================================
// Description : Entra ID guests (UPN contains #EXT#) should rarely receive
//               sensitive group or role memberships. Post-compromise actors
//               and insider threats escalate privileges by adding external
//               accounts to high-privilege groups. This query hunts for
//               such assignments to facilitate triage.
// MITRE ATT&CK: TA0004 Privilege Escalation
//               T1078.004 â€“ Valid Accounts: Cloud Accounts
// Tools       : Manual attacker action, AADInternals, MicroBurst
// Severity    : High
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

AuditLogs
| where TimeGenerated > ago(7d)
| where ActivityDisplayName in (
    "Add member to group",
    "Add member to role",
    "Add eligible member to role",
    "Add app role assignment grant to user")
| extend TargetUserDisplayName = tostring(TargetResources[0].displayName)
| extend TargetUserUPN         = tostring(TargetResources[0].userPrincipalName)
| extend TargetUserId          = tostring(TargetResources[0].id)
| extend GroupOrRole           = tostring(TargetResources[1].displayName)
| extend InitiatedByUPN        = tostring(InitiatedBy.user.userPrincipalName)
| extend InitiatedByApp        = tostring(InitiatedBy.app.displayName)
| extend Actor                 = iff(isnotempty(InitiatedByUPN), InitiatedByUPN, InitiatedByApp)
// Guest accounts use the #EXT# convention in their UPN
| where TargetUserUPN has "#EXT#"
    or TargetUserDisplayName has "(Guest)"
| where Result == "success"
| project
    TimeGenerated,
    Actor,
    TargetUserDisplayName,
    TargetUserUPN,
    GroupOrRole,
    ActivityDisplayName,
    LoggedByService,
    CorrelationId
| order by TimeGenerated desc

// =========================================================================
// HQ-007: Bulk Refresh Token Revocations (Post-Compromise or Evasion)
// =========================================================================
// Description : "Update StsRefreshTokenValidFrom Timestamp" is produced
//               when a user's refresh tokens are revoked (e.g., via
//               Revoke-AzureADUserAllRefreshToken, MCAS response, or an
//               attacker using AADInternals to invalidate sessions after
//               extracting tokens). Three or more revocations in a day by
//               the same actor warrants investigation â€” it may be IR
//               activity or an attacker covering tracks.
// MITRE ATT&CK: TA0005 Defense Evasion
//               T1070 â€“ Indicator Removal
//               T1531 â€“ Account Access Removal
// Tools       : AADInternals, MCAS/MDCA automated response, IR scripts
// Severity    : Medium
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

AuditLogs
| where TimeGenerated > ago(1d)
| where ActivityDisplayName == "Update StsRefreshTokenValidFrom Timestamp"
| extend InitiatedByUPN = tostring(InitiatedBy.user.userPrincipalName)
| extend InitiatedByApp = tostring(InitiatedBy.app.displayName)
| extend Actor          = iff(isnotempty(InitiatedByUPN), InitiatedByUPN, InitiatedByApp)
| extend TargetUser     = tostring(TargetResources[0].displayName)
| extend TargetUPN      = tostring(TargetResources[0].userPrincipalName)
| summarize
    RevocationCount = count(),
    TargetUsers     = make_set(TargetUser, 20),
    TargetUPNs      = make_set(TargetUPN, 20),
    FirstEvent      = min(TimeGenerated),
    LastEvent       = max(TimeGenerated),
    CorrelationIds  = make_set(CorrelationId, 5)
    by Actor
| where RevocationCount >= 3
| extend DurationMinutes = datetime_diff('minute', LastEvent, FirstEvent)
| order by RevocationCount desc

// =========================================================================
// HQ-008: Delegated Permission Grant Including Sensitive API Scopes
// =========================================================================
// Description : Consent events that include high-privilege delegated scopes
//               (Mail.Read, Directory.ReadWrite.All, offline_access, etc.)
//               are a primary indicator of OAuth phishing attacks (Device
//               Code flow abuse via TokenTactics, consent-phishing via
//               AADInternals). The offline_access scope is especially
//               dangerous as it allows long-lived refresh tokens.
// MITRE ATT&CK: TA0006 Credential Access
//               T1528 â€“ Steal Application Access Token
// Tools       : TokenTactics, ROADtools, AADInternals (Device Code flow)
// Severity    : High
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

let SensitiveScopes = dynamic([
    "Mail.Read", "Mail.ReadWrite", "Mail.Send",
    "Files.ReadWrite.All", "Directory.ReadWrite.All",
    "User.ReadWrite.All", "RoleManagement.ReadWrite.Directory",
    "Application.ReadWrite.All", "Sites.FullControl.All",
    "EWS.AccessAsUser.All", "IMAP.AccessAsUser.All",
    "POP.AccessAsUser.All", "SMTP.Send",
    "ChannelMessage.Read.All", "TeamSettings.ReadWrite.All",
    "offline_access"
]);

AuditLogs
| where TimeGenerated > ago(7d)
| where ActivityDisplayName in (
    "Add delegated permission grant",
    "Consent to application")
| extend InitiatedByUPN  = tostring(InitiatedBy.user.userPrincipalName)
| extend InitiatedByApp  = tostring(InitiatedBy.app.displayName)
| extend Actor           = iff(isnotempty(InitiatedByUPN), InitiatedByUPN, InitiatedByApp)
| extend TargetApp       = tostring(TargetResources[0].displayName)
| extend TargetAppId     = tostring(TargetResources[0].id)
| extend PermDetailRaw   = tostring(AdditionalDetails)
// Match any sensitive scope in the AdditionalDetails blob
| where PermDetailRaw has_any (SensitiveScopes)
| extend MatchedScopes = extract_all(
    @"(Mail\.[^\s,""]+|Directory\.[^\s,""]+|offline_access|Application\.[^\s,""]+|Files\.[^\s,""]+|User\.ReadWrite\.All|RoleManagement\.[^\s,""]+|Sites\.[^\s,""]+|EWS\.[^\s,""]+|IMAP\.[^\s,""]+|SMTP\.[^\s,""]+|Channel[^\s,""]+|Team[^\s,""]+)",
    PermDetailRaw)
| project
    TimeGenerated,
    Actor,
    TargetApp,
    TargetAppId,
    MatchedScopes,
    ActivityDisplayName,
    LoggedByService,
    Result,
    CorrelationId
| order by TimeGenerated desc

// =========================================================================
// HQ-009: Credential Added to Existing Application Registration
// =========================================================================
// Description : Adding a new secret or certificate to an already-registered
//               application is a classic post-compromise persistence
//               technique. Attackers (MicroBurst, AADInternals, manual)
//               add credentials to high-value apps to maintain access even
//               after password resets. Filter out changes made by known 
//               CI/CD service accounts.
// MITRE ATT&CK: TA0003 Persistence
//               T1098.001 â€“ Additional Cloud Credentials
// Tools       : MicroBurst, AADInternals, manual attacker, BurpSuite + Graph
// Severity    : High
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

AuditLogs
| where TimeGenerated > ago(7d)
| where ActivityDisplayName in (
    "Update application \u2013 Certificates and secrets management ",
    "Create application \u2013 Certificates and secrets management ",
    "Add service principal credentials",
    "Update service principal")
| mv-expand Prop = TargetResources[0].modifiedProperties
| where tostring(Prop.displayName) has_any (
    "KeyCredentials",
    "PasswordCredentials",
    "Credential",
    "Secret",
    "Certificate")
| extend InitiatedByUPN = tostring(InitiatedBy.user.userPrincipalName)
| extend InitiatedByApp = tostring(InitiatedBy.app.displayName)
| extend Actor          = iff(isnotempty(InitiatedByUPN), InitiatedByUPN, InitiatedByApp)
| extend TargetApp      = tostring(TargetResources[0].displayName)
| extend TargetAppId    = tostring(TargetResources[0].id)
| extend CredType       = tostring(Prop.displayName)
| extend NewValue       = tostring(Prop.newValue)
| extend OldValue       = tostring(Prop.oldValue)
| where Result == "success"
// Optionally exclude known CI/CD automation accounts:
// | where Actor !in ("devops-pipeline@contoso.com", "terraform-sp")
| project
    TimeGenerated,
    Actor,
    TargetApp,
    TargetAppId,
    CredType,
    NewValue,
    OldValue,
    ActivityDisplayName,
    LoggedByService,
    CorrelationId
| order by TimeGenerated desc

// =========================================================================
// HQ-010: Domain Federation / Authentication Configuration Changes
// =========================================================================
// Description : Modifying a domain's authentication type (Managed â†’ 
//               Federated) is the cornerstone of the "Golden SAML" and
//               AADInternals federation abuse attacks. Attackers with 
//               Global Admin privilege can federate a domain with a rogue
//               IDP and forge SAML tokens for any user without knowing
//               their passwords. Any change here is extremely high-fidelity.
// MITRE ATT&CK: TA0003 Persistence
//               T1484.002 â€“ Domain Trust Modification
//               TA0005 Defense Evasion
//               T1606.002 â€“ Forge Web Credentials: SAML Token
// Tools       : AADInternals (ConvertTo-AADIntBackdoor), manual attacker
// Severity    : Critical
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

AuditLogs
| where TimeGenerated > ago(90d)
| where ActivityDisplayName in (
    "Set domain authentication",
    "Set federation settings on domain",
    "Set DirSyncEnabled flag",
    "Set Company Information",
    "Set federation settings",
    "Update domain",
    "Verify domain")
| extend InitiatedByUPN  = tostring(InitiatedBy.user.userPrincipalName)
| extend InitiatedByApp  = tostring(InitiatedBy.app.displayName)
| extend Actor           = iff(isnotempty(InitiatedByUPN), InitiatedByUPN, InitiatedByApp)
| extend TargetDomain    = tostring(TargetResources[0].displayName)
| extend TargetId        = tostring(TargetResources[0].id)
| mv-expand Prop = TargetResources[0].modifiedProperties
| extend PropName        = tostring(Prop.displayName)
| extend OldValue        = tostring(Prop.oldValue)
| extend NewValue        = tostring(Prop.newValue)
| where Result == "success"
| project
    TimeGenerated,
    Actor,
    ActivityDisplayName,
    TargetDomain,
    TargetId,
    PropName,
    OldValue,
    NewValue,
    LoggedByService,
    CorrelationId
| order by TimeGenerated desc
